//! Fixture parity and regression tests for the LongCat-AudioDiT
//! family.
//!
//! Fixtures live in `testdata/tts_longcat_audiodit/`, regenerated by
//! `tools/gen_longcat_audiodit_fixtures.py` against the pinned
//! mlx-audio commit. The e2e cases replay the recorded
//! `mx.random.normal` draws in reference order; waveforms and latents
//! run under absolute f32 gates.

use std::path::{Path, PathBuf};

use serde_json::Value;

use super::text_encoder::check_mask_len;
use super::{check_prompt_fits, check_steps, Model, Noise, VaeConfig};
use crate::lm::Weights;
use crate::SpeechError;

fn testdata(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("testdata/tts_longcat_audiodit")
        .join(name)
}

fn read_json(path: &Path) -> Value {
    let text = std::fs::read_to_string(path).expect("fixture json");
    serde_json::from_str(&text).expect("fixture json")
}

fn f32_vec(value: &Value) -> Vec<f32> {
    value
        .as_array()
        .expect("values")
        .iter()
        .map(|v| v.as_f64().expect("value") as f32)
        .collect()
}

fn i32_vec(value: &Value) -> Vec<i32> {
    value
        .as_array()
        .expect("ids")
        .iter()
        .map(|v| v.as_i64().expect("int") as i32)
        .collect()
}

fn max_abs_diff(a: &[f32], b: &[f32]) -> f32 {
    assert_eq!(a.len(), b.len(), "length mismatch");
    a.iter()
        .zip(b)
        .map(|(x, y)| (x - y).abs())
        .fold(0.0f32, f32::max)
}

/// Measured against the fixture outputs when the gate was frozen; the
/// tiny stack keeps the f32 accumulation noise far below the gates.
/// The waveform gate is relative: the unbounded conv decoder scales
/// with the fixture's random weights.
const LATENT_TOLERANCE: f32 = 2e-4;
const WAVEFORM_TOLERANCE: f32 = 2e-4;

fn assert_relative(got: &[f32], want: &[f32], relative: f32, what: &str) {
    let magnitude = want.iter().fold(0.0f32, |a, v| a.max(v.abs()));
    let gate = relative * magnitude;
    let diff = max_abs_diff(got, want);
    assert!(diff <= gate, "{what} diff {diff} exceeds {gate}");
}

/// Replays the recorded reference `mx.random.normal` draws in order.
struct RecordedNoise {
    draws: Vec<Vec<f32>>,
    cursor: usize,
}

impl RecordedNoise {
    fn new(traces: &Value) -> Self {
        Self {
            draws: traces["draws"]
                .as_array()
                .expect("draws")
                .iter()
                .map(|d| f32_vec(&d["values"]))
                .collect(),
            cursor: 0,
        }
    }
}

impl Noise for RecordedNoise {
    fn normal(&mut self, n: usize) -> Vec<f32> {
        let draw = self
            .draws
            .get(self.cursor)
            .unwrap_or_else(|| panic!("draw {} missing", self.cursor))
            .clone();
        self.cursor += 1;
        assert_eq!(draw.len(), n, "draw {} shape", self.cursor - 1);
        draw
    }
}

fn load_model(case: &str) -> Model {
    let dir = testdata(case);
    let config_value = crate::quant::read_json(&dir.join("config.json")).expect("config");
    let config = super::ModelConfig::from_json(&config_value);
    let weights = Weights::open(&dir).expect("weights");
    Model::load(&weights, config).expect("model loads")
}

#[test]
fn config_defaults_match_the_reference() {
    let config = super::ModelConfig::from_json(&serde_json::json!({}));
    assert_eq!(config.dit_dim, 1536);
    assert_eq!(config.dit_depth, 24);
    assert_eq!(config.dit_heads, 24);
    assert_eq!(config.dit_text_dim, 768);
    assert!(config.dit_bias);
    assert_eq!(config.dit_adaln_type, "global");
    assert!(config.dit_long_skip);
    assert!(config.dit_text_conv);
    assert!(config.dit_qk_norm);
    assert_eq!(config.repa_dit_layer, 8);
    assert_eq!(config.latent_dim, 64);
    assert_eq!(config.sampling_rate, 24000);
    assert_eq!(config.latent_hop, 2048);
    assert_eq!(config.max_wav_duration, 30.0);
    assert!(config.text_add_embed);
    assert!(config.text_norm_feat);
    assert_eq!(config.vae_config.channels, 128);
    assert_eq!(config.vae_config.c_mults, vec![1, 2, 4, 8, 16]);
    assert_eq!(config.vae_config.strides, vec![2, 4, 4, 8, 8]);
    assert_eq!(config.vae_config.downsampling_ratio, 2048);
    assert_eq!(config.vae_config.scale, 0.71);
    assert_eq!(config.text_encoder_config.vocab_size, 256384);
    assert_eq!(config.text_encoder_config.d_model, 768);
    assert_eq!(config.text_encoder_config.num_layers, 12);
    assert!(config.text_encoder_config.is_gated_act);
}

#[test]
fn text_normalization_and_duration_match_the_reference() {
    let traces = read_json(&testdata("text/traces.json"));
    let inputs = traces["inputs"].as_array().expect("inputs");
    for (i, input) in inputs.iter().enumerate() {
        let input = input.as_str().expect("text");
        let want = traces["normalized"][i].as_str().expect("normalized");
        assert_eq!(super::normalize_text(input), want, "normalize {input:?}");
        let duration = super::approx_duration(
            &super::normalize_text(input),
            traces["durations"][i].as_f64().expect("duration"),
        );
        assert!(
            (duration - traces["durations"][i].as_f64().unwrap()).abs() < 1e-9,
            "duration {input:?}"
        );
    }
    // The prompt builder concatenates the normalized transcript.
    assert_eq!(
        super::prompt_text("Hello", Some("a reference")),
        "a reference hello"
    );
}

#[test]
fn dit_forward_matches_the_reference() {
    let traces = read_json(&testdata("dit/traces.json"));
    let model = load_model("dit");
    let seq = 6usize;
    let cond_seq = 5usize;
    let mask = vec![true; seq];
    let text_mask = vec![true, true, true, false, false];
    let output = model.transformer.forward(
        &f32_vec(&traces["x"]),
        seq,
        &f32_vec(&traces["text"]),
        cond_seq,
        traces["time"].as_f64().expect("time") as f32,
        Some(&mask),
        Some(&text_mask),
        Some(model.config.repa_dit_layer),
        &f32_vec(&traces["latent_cond"]),
    );
    let want = f32_vec(&traces["output"]);
    assert_eq!(output.len(), want.len());
    let diff = max_abs_diff(&output, &want);
    assert!(diff < LATENT_TOLERANCE, "dit output diff {diff}");
}

#[test]
fn generation_matches_the_reference() {
    let traces = read_json(&testdata("generate/traces.json"));
    let mut model = load_model("generate");
    let ids = i32_vec(&traces["input_ids"]);
    let mask = f32_vec(&traces["attention_mask"]);
    let params = super::GenerateParams {
        steps: traces["steps"].as_u64().expect("steps") as usize,
        cfg_strength: traces["cfg_strength"].as_f64().expect("cfg") as f32,
        guidance_method: traces["guidance_method"]
            .as_str()
            .expect("method")
            .to_owned(),
    };
    let mut noise = RecordedNoise::new(&traces);
    let got = model
        .generate(
            traces["prompt"].as_str().expect("prompt"),
            &ids,
            &mask,
            &params,
            &mut noise,
            None,
            None,
        )
        .expect("generate runs");
    assert_eq!(noise.cursor, 1, "one draw consumed");
    let want_wave = f32_vec(&traces["waveform"]);
    assert_eq!(got.waveform.len(), want_wave.len(), "sample count");
    assert_relative(
        &got.waveform,
        &want_wave,
        WAVEFORM_TOLERANCE,
        "generate waveform",
    );
    assert_eq!(
        got.sample_rate,
        traces["sample_rate"].as_u64().expect("rate") as u32
    );
}

#[test]
fn voice_prompt_matches_the_reference() {
    let traces = read_json(&testdata("voice/traces.json"));
    let model = load_model("voice");
    // encode_prompt_audio parity with the first recorded draw.
    let mut encode_noise = RecordedNoise::new(&traces);
    let (prompt_latent, prompt_frames) = model
        .encode_prompt_audio(&f32_vec(&traces["ref_audio"]), &mut encode_noise)
        .expect("prompt encode");
    assert_eq!(
        prompt_frames as i64,
        traces["prompt_frames"].as_i64().expect("frames")
    );
    let want_latent = f32_vec(&traces["prompt_latent"]);
    assert_eq!(prompt_latent.len(), want_latent.len());
    // The tiny VAE rides in the hundreds; the gate is relative to the
    // reference magnitude.
    let magnitude = want_latent.iter().fold(0.0f32, |a, v| a.max(v.abs()));
    let diff = max_abs_diff(&prompt_latent, &want_latent);
    assert!(
        diff < LATENT_TOLERANCE * magnitude,
        "prompt latent diff {diff} (magnitude {magnitude})"
    );

    let mut model = model;
    let ids = i32_vec(&traces["input_ids"]);
    let mask = f32_vec(&traces["attention_mask"]);
    let params = super::GenerateParams {
        steps: traces["steps"].as_u64().expect("steps") as usize,
        cfg_strength: traces["cfg_strength"].as_f64().expect("cfg") as f32,
        guidance_method: traces["guidance_method"]
            .as_str()
            .expect("method")
            .to_owned(),
    };
    let mut noise = RecordedNoise::new(&traces);
    let got = model
        .generate(
            traces["prompt"].as_str().expect("prompt"),
            &ids,
            &mask,
            &params,
            &mut noise,
            Some(&f32_vec(&traces["ref_audio"])),
            Some(traces["ref_text"].as_str().expect("ref text")),
        )
        .expect("generate runs");
    assert_eq!(noise.cursor, 2, "VAE draw then latent draw");
    let want_wave = f32_vec(&traces["waveform"]);
    assert_eq!(got.waveform.len(), want_wave.len(), "sample count");
    assert_relative(
        &got.waveform,
        &want_wave,
        WAVEFORM_TOLERANCE,
        "voice waveform",
    );
}

