// The guards below run without a checkpoint: they are the pure checks
// that `generate` and the loaders call before touching any tensor.

#[test]
fn steps_below_two_are_rejected() {
    // One step would run zero Euler updates and return raw noise.
    assert!(check_steps(0).is_err());
    assert!(check_steps(1).is_err());
    assert!(check_steps(2).is_ok());
}

#[test]
fn voice_prompt_at_or_over_the_cap_is_rejected() {
    let max_frames = 100;
    // Over the cap: would underflow `total_duration - prompt_dur`.
    assert!(check_prompt_fits(101, max_frames).is_err());
    // Exactly the cap: no frames left to generate.
    assert!(check_prompt_fits(max_frames, max_frames).is_err());
    assert!(check_prompt_fits(max_frames - 1, max_frames).is_ok());
}

#[test]
fn attention_mask_must_match_input_ids() {
    let ids = [1, 2, 3];
    assert!(check_mask_len(&ids, &[1.0, 1.0]).is_err());
    assert!(check_mask_len(&ids, &[1.0, 1.0, 1.0, 1.0]).is_err());
    assert!(check_mask_len(&ids, &[1.0, 1.0, 0.0]).is_ok());
}

#[test]
fn vae_strides_must_match_c_mults() {
    // A short stride list used to panic on indexing during VAE load.
    let short = VaeConfig::from_json(&serde_json::json!({
        "c_mults": [1, 2, 4],
        "strides": [2, 4],
    }));
    match short.validate() {
        Err(SpeechError::BadConfig { field, .. }) => {
            assert_eq!(field, "vae_config.strides");
        }
        other => panic!("expected BadConfig for short strides, got {other:?}"),
    }

    let empty = VaeConfig::from_json(&serde_json::json!({
        "c_mults": [],
        "strides": [],
    }));
    assert!(matches!(
        empty.validate(),
        Err(SpeechError::BadConfig { .. })
    ));

    assert!(VaeConfig::default().validate().is_ok());
}
